#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"
#include "gui_forms/controls/shared_property_enums.hpp"
#include "gui_forms/controls/label_values.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// FormLayout's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/form_layout.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// The caption column's width in logical units, or 0 for the widest caption's; finite and 0 to 4096 (std::invalid_argument otherwise).
template <typename Declaring>
struct FormLayoutCaptionWidthCapability {
    PropertyCell<double, FormLayoutCaptionWidthCapability<Declaring>> caption_width{0.0};

    static void assign(FormLayoutCaptionWidthCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.caption_width), incoming);
        if (!capability.caption_width.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.caption_width));
    }
};

// Where each caption sits in the caption column: at its start (near, the default), centre or end (far, beside the control).
template <typename Declaring>
struct FormLayoutCaptionAlignmentCapability {
    PropertyCell<HorizontalAlignment, FormLayoutCaptionAlignmentCapability<Declaring>> caption_alignment{HorizontalAlignment::near};

    static void assign(FormLayoutCaptionAlignmentCapability& capability, HorizontalAlignment incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.caption_alignment), incoming);
        if (!capability.caption_alignment.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.caption_alignment));
    }
};

// The space between rows in logical units; finite and 0 to 256 (std::invalid_argument otherwise).
template <typename Declaring>
struct FormLayoutRowSpacingCapability {
    PropertyCell<double, FormLayoutRowSpacingCapability<Declaring>> row_spacing{6.0};

    static void assign(FormLayoutRowSpacingCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.row_spacing), incoming);
        if (!capability.row_spacing.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.row_spacing));
    }
};

// The space between the caption column and the controls in logical units; finite and 0 to 256 (std::invalid_argument otherwise).
template <typename Declaring>
struct FormLayoutColumnSpacingCapability {
    PropertyCell<double, FormLayoutColumnSpacingCapability<Declaring>> column_spacing{8.0};

    static void assign(FormLayoutColumnSpacingCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.column_spacing), incoming);
        if (!capability.column_spacing.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.column_spacing));
    }
};

// Every FormLayout capability, in the order the declaring class takes them.
template <typename Declaring>
struct FormLayoutCapabilities : public FormLayoutCaptionWidthCapability<Declaring>,
                                public FormLayoutCaptionAlignmentCapability<Declaring>,
                                public FormLayoutRowSpacingCapability<Declaring>,
                                public FormLayoutColumnSpacingCapability<Declaring> {};

} // namespace gui_forms
